/*
    "sRGB vs Gamma 2.2" by @XorDev

    I wanted to clarify the subtle difference between sRGB and gamma 2.2

    Red: sRGB shown
    Green: gamma 2.2
    Blue: Linear

    As you can see there's difference in the low end and upper middle
    This is an expansion to my gamma tutorial:
    https://www.shadertoy.com/view/XXyBRR
*/
#define GAMMA 2.2

//Decode gamma to linear color
float gamma_decode(float srgb)
{
    return pow(srgb, GAMMA);
}

//Encode linear color to gamma
float gamma_encode(float lrgb)
{
    return pow(lrgb, 1.0/GAMMA);
}

//Decode sRGB to linear
float SRGB_decode(float srgb)
{
    return mix(
        srgb / 12.92,
        pow((srgb + 0.055) / 1.055, 2.4),
        step(0.04045, srgb)
    );
}
//Encode linear to sRGB
float SRGB_encode(float lrgb)
{
    return mix(
        12.92 * lrgb,
        1.055 * pow(lrgb, 1.0 / 2.4) - 0.055,
        step(0.0031308, lrgb)
    );
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //Normalized and aspect corrected UVs
    vec2 uv = (fragCoord -0.5 * iResolution.xy)/ iResolution.y+0.5;

    //Compute the 3 graphs
    vec3 y = vec3(SRGB_decode(uv.x), gamma_decode(uv.x), uv.x) - uv.y;
    //Width for anti-aliasing
    vec3 w = fwidth(y);

    //Colored lines
    vec3 col = smoothstep(2.0*w, 1.0*w, abs(y));

    //Encode in sRGB
    fragColor = vec4(SRGB_encode(col.r), SRGB_encode(col.g), SRGB_encode(col.b), 1.0);
}
